import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Inspect{public static void main(String[]args)throws Exception{Set<String>names=Set.of("Gl37","Gl37$State","Laser32","LaserLate37","LateLaser37","Gpu12","Gpu12$State","EntityLight14","EntityLight14$Hit","G6","G6$State");int count=0;for(String path:args)try(ZipFile z=new ZipFile(path)){for(var e:Collections.list(z.entries())){String n=e.getName();if(n.endsWith(".class")&&names.contains(n.substring(n.lastIndexOf('/')+1,n.length()-6))){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);for(var m:c.methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);count++;}}}if(count!=12)throw new AssertionError(count);System.out.println("FINAL_IRIS_SAMPLER_ENTITY_AND_LATE_LASER_BYTECODE_CHECKS="+count);}}
